import { Link } from "react-router-dom";
import Teachersidebar from "./Teachersidebar";
import { useState,useEffect } from "react";
import {Routes as Switch, Route} from 'react-router-dom';
import axios from "axios";
function Addcourse(){
    const[cats,setCats]=useState([]);
    useEffect(()=>{
        try{
            axios.get("http://127.0.0.1:8000/api/category/").then((response)=>{
                setCats(response.data);
                console.log(response.data);
            })
        }catch(error){
            console.log(error);
        }},[])   
 return (
    <div className="container mt-4">
        <div className="row">
            <aside className="col-md-3">
                <Teachersidebar></Teachersidebar>
            </aside>
            <section className="col-md-9">
                <div className="card">
                        <h5 className="card-header">Add Course</h5>
                        <div className="card-body">
                            <form>
                                <div className="mb-3">
                                    <label htmlFor="catregory" className="form-label">Category</label>
                                    <select name="category" className="form-control"/>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="name" className="form-label">Title</label>
                                    <input type="text" className="form-control" id="name"/>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="description" className="form-label">Description</label>
                                    <textarea className="form-control"></textarea>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="video" className="form-label">Featured Image</label>
                                    <input type="file" id="img" className="form-control"/>
                                </div>

                                <div className="mb-3">
                                    <label htmlFor="Technology" className="form-label">Technologies used</label>
                                    <textarea className="form-control"></textarea>
    
                                </div>
                                <button type="submit" className="btn btn-primary">submit</button>
                            </form>
                        </div>
                    </div>
            </section>
        </div>
      </div>
 );
}
export default Addcourse
